def build_ends_with(pattern, alphabet):
    n = len(pattern)
    delta = {}
    for i in range(n + 1):
        delta[i] = {}
        for ch in alphabet:
            cand = pattern[:i] + ch
            k = min(len(cand), n)
            while k > 0 and cand[-k:] != pattern[:k]:
                k -= 1
            delta[i][ch] = k
    return {"start": 0, "accept": {n}, "delta": delta}

def run_dfa(m, s):
    state = m["start"]
    for ch in s:
        if ch not in m["delta"].get(state, {}):
            return False
        state = m["delta"][state][ch]
    return state in m["accept"]

